<?php
require_once __DIR__.'/core.php';tt_require_login();$db=tt_db_open(true);$id=(int)$_SESSION['id'];$notice='';$error='';$mediaReady=tt_schema_table_exists($db,'profile_media');
if($_SERVER['REQUEST_METHOD']==='POST'&&isset($_POST['save'])){$about=substr(trim((string)($_POST['aboutcontent']??'')),0,32768);$s=tt_prepare($db,'UPDATE `accounts` SET `aboutcontent`=? WHERE `id`=?');$s->bind_param('si',$about,$id);if($s->execute()){$notice='Account description saved.';$_SESSION['aboutcontent']=$about;}else{$error=$s->error;}$s->close();}
if($_SERVER['REQUEST_METHOD']==='POST'&&isset($_POST['delete_profile_media'])){if(!$mediaReady)$error='Profile media needs one protected schema maintenance run first.';else{$s=tt_prepare($db,'DELETE FROM `profile_media` WHERE `account_id`=?');$s->bind_param('i',$id);$s->execute();$s->close();$notice='Profile media removed.';}}
if($_SERVER['REQUEST_METHOD']==='POST'&&isset($_POST['save_profile_media'])){if(!$mediaReady)$error='Profile media needs one protected schema maintenance run first.';elseif(empty($_FILES['profile_media'])||!is_uploaded_file($_FILES['profile_media']['tmp_name']))$error='Choose an image, audio, or video file.';else{$f=$_FILES['profile_media'];$size=(int)($f['size']??0);if($size<=0||$size>1572864)$error='Profile media must be between 1 byte and 1.5 MB.';else{$tmp=(string)$f['tmp_name'];$fi=new finfo(FILEINFO_MIME_TYPE);$mime=(string)$fi->file($tmp);if(!preg_match('#^(image/(png|jpeg|gif|webp)|audio/(mpeg|ogg|wav|x-wav|mp4)|video/(mp4|webm|ogg))$#i',$mime))$error='Supported profile media: PNG/JPEG/GIF/WebP, MP3/OGG/WAV/M4A, MP4/WebM/OGG.';else{$data=(string)file_get_contents($tmp);$name=substr(basename((string)($f['name']??'profile-media')),0,255);$s=tt_prepare($db,'INSERT INTO `profile_media` (`account_id`,`filename`,`mime_type`,`size_bytes`,`data`,`updated_at`) VALUES (?,?,?,?,?,UTC_TIMESTAMP()) ON DUPLICATE KEY UPDATE `filename`=VALUES(`filename`),`mime_type`=VALUES(`mime_type`),`size_bytes`=VALUES(`size_bytes`),`data`=VALUES(`data`),`updated_at`=UTC_TIMESTAMP()');$s->bind_param('issis',$id,$name,$mime,$size,$data);if($s->execute())$notice='Profile media saved.';else$error=$s->error;$s->close();}}}}
$s=tt_prepare($db,'SELECT `username`,`email`,`aboutcontent`,`hostmode`,`created_at`,`last_login_at`,`protected_account` FROM `accounts` WHERE `id`=? LIMIT 1');$s->bind_param('i',$id);$s->execute();$row=$s->get_result()->fetch_assoc();$s->close();$media=null;if($mediaReady){$s=tt_prepare($db,'SELECT `filename`,`mime_type`,`size_bytes`,`updated_at` FROM `profile_media` WHERE `account_id`=? LIMIT 1');$s->bind_param('i',$id);$s->execute();$media=$s->get_result()->fetch_assoc();$s->close();}$db->close();if(!$row)tt_fail('Account record was not found.',404,'Account');
function tt_profile_media_markup(int $id,?array $m):string{if(!$m)return '';$src='profile_media.php?id='.$id;$mime=strtolower((string)$m['mime_type']);if(str_starts_with($mime,'image/'))return '<img class="profile-media" src="'.$src.'" alt="Profile media" loading="lazy">';if(str_starts_with($mime,'video/'))return '<video class="profile-media" src="'.$src.'" controls preload="metadata"></video>';if(str_starts_with($mime,'audio/'))return '<audio class="profile-audio" src="'.$src.'" controls preload="metadata"></audio>';return '<a href="'.$src.'">Open profile media</a>';}
?><!doctype html><html class="tabletime"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><link rel="stylesheet" href="style.php"><title>Tabletime · Account</title></head><body><?php tt_nav('account.php');?><main class="content"><h2>Account</h2><?php if($notice):?><p class="notice ok"><?=tt_h($notice)?></p><?php endif;?><?php if($error):?><p class="notice error"><?=tt_h($error)?></p><?php endif;?><section class="card"><p><strong>Name:</strong> <?=tt_h($row['username'])?></p><p><strong>Email:</strong> <?=tt_h($row['email'])?></p><p><strong>Node role:</strong> <?=((int)$row['hostmode']>=2?'Admin/coordinator':((int)$row['hostmode']>=1?'Host':'Client'))?></p><p><strong>Created:</strong> <?=tt_h($row['created_at'])?></p><p><strong>Last login:</strong> <?=tt_h($row['last_login_at'])?></p><div class="actions"><a href="adcredits.php">Ad credits & revenue</a><a href="usrchange.php">Change credentials</a><a href="colorpick.php">Theme</a><a href="file.php">Files</a></div></section><section class="card tt-expand-card" data-tt-expandable="1" aria-expanded="false"><h3>Profile picture / media</h3><?php if(!$mediaReady):?><p class="notice">Run protected schema maintenance once to enable profile media.</p><?php elseif($media):?><?=tt_profile_media_markup($id,$media)?><p class="meta"><?=tt_h($media['filename'])?> · <?=number_format(((int)$media['size_bytes'])/1024,1)?> KB · updated <?=tt_h($media['updated_at'])?></p><form method="post" class="inline-form"><button type="submit" name="delete_profile_media" value="1">Remove profile media</button></form><?php else:?><p class="meta">No profile media uploaded yet.</p><?php endif;?><?php if($mediaReady):?><form method="post" enctype="multipart/form-data"><label>Image, audio, or video (max 1.5 MB)</label><input type="file" name="profile_media" accept="image/*,audio/*,video/*" required><button type="submit" name="save_profile_media" value="1">Save profile media</button></form><?php endif;?></section><form method="post"><h3>Profile description</h3><textarea name="aboutcontent" maxlength="32768"><?=tt_h($row['aboutcontent'])?></textarea><input type="submit" name="save" value="Save description"></form></main></body></html>